    27	    public synchronized Reservation create(NewReservation request) {
    28	        if (!request.checkOut().isAfter(request.checkIn())) {
    29	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
    30	        }
    31	        if (request.guests() < 1) {
    32	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
    33	        }
    34	        if (request.children() < 0) {
    35	            throw new HotelException(ErrorCode.INVALID_REQUEST, "children count cannot be negative");
    36	        }
    37	        Room room = rooms.find(request.roomNumber())
    38	                .orElseThrow(() -> new HotelException(
    39	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
    40	        int totalOccupants = request.guests() + request.children();
    41	        if (totalOccupants > room.capacity()) {
    42	            throw new HotelException(
    43	                    ErrorCode.CAPACITY_EXCEEDED,
    44	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
    45	        }
    46	        if (store.isRoomTaken(room.number(), request.checkIn(), request.checkOut())) {
    47	            throw new HotelException(
    48	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
    49	        }
    50	        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan());
    51	        return store.add(request, price);
    52	    }
